/* Uses the existing admin token and API. Never embeds credentials or bill instance IDs. */
var FINANCE=null,FINANCE_PAGE=0,FINANCE_LOAD=0;
function financeMoney(n){return n==null?'未核定':'¥'+Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:6});}
function financeProvider(p){return p==='volcengine'?'火山引擎':p==='aliyun-bailian'?'阿里云百炼':p;}
function financeProduct(p){return {'sfm':'百炼模型与搜索','Doubao-Seedream':'Seedream 图片生成','ark_bd':'方舟服务 · ark_bd','ark_open_source_llm':'方舟开源模型服务'}[p]||p;}
function loadCostReport(days){
  var load=++FINANCE_LOAD;days=days||30;
  [7,14,30].forEach(function(d){var b=q('cr'+d);if(b){b.classList.toggle('on',d===days);b.setAttribute('aria-pressed',d===days?'true':'false');}});
  q('costReport').innerHTML='<div class="empty" role="status">正在读取官方账单与调用台账…</div>';
  api('/admin/finance?days='+days).then(function(j){if(load!==FINANCE_LOAD)return;FINANCE=j;FINANCE_PAGE=0;renderFinance();})
    .catch(function(e){if(load===FINANCE_LOAD)q('costReport').innerHTML='<div class="err" role="alert">'+esc(e.message)+'。未读取成功，不代表费用为零。</div><button class="btnNew" onclick="loadCostReport('+days+')">重新读取</button>';});
}
function renderFinance(){
  var j=FINANCE;if(!j)return;
  var h='<div class="finance-hero"><div>两平台官方账单 · 应付金额</div><div class="amount">'+financeMoney(j.officialPayableCny)+'</div><div>'+esc(j.window.start)+' 至 '+esc(j.window.end)+'，北京时间</div><p>这是平台已出账的服务消费。充值、用户额度扣减与现金收入分别核算。</p></div>';
  h+='<div class="finance-grid">';['volcengine','aliyun-bailian'].forEach(function(p){var synced=j.coverage.daysByProvider[p]||0;h+='<div class="finance-card"><div>'+financeProvider(p)+'</div><strong>'+financeMoney(j.byProvider[p]||0)+'</strong><small>已同步 '+synced+' / '+j.window.days+' 天 · '+(synced===j.window.days?'日期覆盖完整':'仍有日期待同步')+'</small></div>';});h+='</div>';
  if(j.dataStatus!=='complete'||!j.coverage.complete)h+='<div class="warn" role="alert">当前数据不完整。缺少 '+j.coverage.missing.length+' 个平台日期，请勿据此结算。</div>';
  h+='<div class="finance-grid"><div class="finance-card"><div>App 调用成本估算</div><strong>'+financeMoney(j.trackedCallEstimateCny)+'</strong><small>按每次实际用量及已核验单价计算；历史台账尚不完整。</small></div><div class="finance-card"><div>用户额度已扣减</div><strong>'+financeMoney(j.userQuotaDebitedCny)+'</strong><small>这不是平台成本，也不是本期收款。</small></div></div>';
  h+='<div class="finance-note"><b>为什么和旧看板不一致？</b><p>旧聊天流水混用了会员扣费与供应商成本。新看板分别展示，旧数据不硬改。</p><p>平台应付与已记录调用估算相差 <b>'+financeMoney(j.differenceCny)+'</b>。可能包含历史缺失、其他项目调用、内部辅助调用及出账时间差，不能直接认定为漏扣或利润。</p><p>尚未核价的调用 '+j.unknownCostCalls+' 笔；旧口径聊天流水 '+j.legacyUnknownCostRows+' 笔。</p></div>';
  h+='<h3>钱花在哪里</h3><div class="finance-grid">';Object.keys(j.byProduct).filter(function(p){return j.byProduct[p]!==0;}).sort(function(a,b){return j.byProduct[b]-j.byProduct[a];}).forEach(function(p){var pct=j.officialPayableCny>0?Math.max(0,Math.min(100,j.byProduct[p]/j.officialPayableCny*100)):0;h+='<div class="finance-card"><div>'+esc(financeProduct(p))+'</div><strong>'+financeMoney(j.byProduct[p])+'</strong><div class="finance-bar"><i style="width:'+pct+'%"></i></div></div>';});h+='</div>';
  h+='<details class="cfgwrap"><summary>逐日支出</summary><div class="bill-scroll"><table><thead><tr><th scope="col">日期</th><th scope="col">官方应付</th></tr></thead><tbody>';Object.keys(j.byDay).sort().reverse().forEach(function(d){h+='<tr><td>'+esc(d)+'</td><td>'+financeMoney(j.byDay[d])+'</td></tr>';});h+='</tbody></table></div></details>';
  h+='<details class="cfgwrap"><summary>账单明细 · '+j.details.length+' 条</summary><p>保留平台全部计费项，包含模型、缓存、图片与其他服务。</p><button class="btnNew" onclick="exportFinance()">导出 CSV</button><div id="billRows"></div></details>';
  h+='<details class="cfgwrap"><summary>每笔用户调用与扣费</summary><p>按订单号记录模型、Token、成本估算和实际额度扣减。</p><button class="btnNew" onclick="loadFinanceCalls(0)">读取最近调用</button><div id="financeCalls"></div></details>';
  h+='<div class="finance-note">'+j.notes.map(function(n){return '<p>'+esc(n)+'</p>';}).join('')+'<p>最近同步：'+esc(fmtTime(j.syncStatus.lastSync))+'；页面刷新：'+esc(fmtTime(j.generatedAt))+'</p></div>';
  q('costReport').innerHTML=h;renderBillRows();
}
function renderBillRows(){var rows=FINANCE.details,start=FINANCE_PAGE*20,limit=Math.ceil(rows.length/20)||1;var h='<div class="bill-scroll"><table><thead><tr><th>日期 / 平台</th><th>产品 / 计费项</th><th>用量</th><th>应付金额</th></tr></thead><tbody>';
  rows.slice(start,start+20).forEach(function(r){h+='<tr><td>'+esc(r.day)+'<br>'+esc(financeProvider(r.provider))+'</td><td>'+esc(r.model||r.product)+'<br><span class="mono">'+esc(r.item)+'</span></td><td>'+esc(r.usage==null?'未提供':r.usage)+' '+esc(r.unit)+'</td><td>'+financeMoney(r.amount)+'</td></tr>';});
  h+='</tbody></table></div><div class="bill-pages"><button onclick="financePage(-1)" '+(FINANCE_PAGE===0?'disabled':'')+'>上一页</button><span>第 '+(FINANCE_PAGE+1)+' / '+limit+' 页</span><button onclick="financePage(1)" '+(FINANCE_PAGE+1>=limit?'disabled':'')+'>下一页</button></div>';q('billRows').innerHTML=h;
}
function financePage(n){FINANCE_PAGE=Math.max(0,Math.min(Math.ceil(FINANCE.details.length/20)-1,FINANCE_PAGE+n));renderBillRows();}
function exportFinance(){var safe=function(v){var s=String(v==null?'':v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};var rows=[['日期','平台','产品','模型','计费项','用量','单位','官方应付元']].concat(FINANCE.details.map(function(r){return[r.day,financeProvider(r.provider),r.product,r.model,r.item,r.usage,r.unit,r.amount];}));var url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(function(r){return r.map(safe).join(',');}).join('\r\n')],{type:'text/csv;charset=utf-8'}));var a=document.createElement('a');a.href=url;a.download='中防AI-官方账单-'+FINANCE.window.start+'-'+FINANCE.window.end+'.csv';a.click();setTimeout(function(){URL.revokeObjectURL(url);},5000);}
function loadFinanceCalls(page){var target=q('financeCalls');target.innerHTML='<div class="empty">正在读取…</div>';var w=FINANCE.window;api('/admin/model-calls?start='+encodeURIComponent(new Date(w.startMs).toISOString())+'&end='+encodeURIComponent(new Date(w.endMs).toISOString())+'&limit=20&page='+page).then(function(j){var h='<div class="bill-scroll"><table><thead><tr><th>时间 / 订单</th><th>用户 / 模型</th><th>输入 / 缓存 / 输出 Token</th><th>成本估算 / 扣额度</th><th>状态</th></tr></thead><tbody>';j.rows.forEach(function(r){h+='<tr><td>'+esc(fmtTime(r.startedAt))+'<br><span class="mono">'+esc(r.orderId)+'</span></td><td>'+esc(r.accountId)+'<br><span class="mono">'+esc(r.model)+'</span></td><td>'+esc(r.inputTokens??'—')+' / '+esc(r.cachedInputTokens??'—')+' / '+esc(r.outputTokens??'—')+'</td><td>'+financeMoney(r.supplierCostEstimateCny)+'<br>'+financeMoney(r.priceCny)+'</td><td>'+esc(r.chargeState==='committed'?'已扣额度':r.chargeState==='pending_cost'?'待核账':r.status==='cached'?'缓存免扣':'未结算')+'</td></tr>';});h+='</tbody></table></div><div class="bill-pages"><button onclick="loadFinanceCalls('+Math.max(0,page-1)+')" '+(page===0?'disabled':'')+'>上一页</button><span>第 '+(page+1)+' 页</span><button onclick="loadFinanceCalls('+(page+1)+')" '+(!j.hasMore?'disabled':'')+'>下一页</button></div>';target.innerHTML=h;}).catch(function(e){target.textContent=e.message;});}
